export async function fetchTicket(id:number,signal:AbortSignal):Promise<Ticket>{signal.throwIfAborted();const ticket=tickets.get(id);if(!ticket)throw new TicketFailure(404);return {...ticket};}
export async function deleteTicket(id:number):Promise<void>{if(!tickets.delete(id))throw new TicketFailure(404);}

import {useEffect,useState} from "react";
import {fetchTicket,TicketFailure,type Ticket} from "./ticketApi";
export type TicketState={id:number|null;status:"loading"}|{id:number;status:"ready";ticket:Ticket}|{id:number;status:"missing"|"error"};
export function useTicket(id:number|null):TicketState{
 const [state,setState]=useState<TicketState>({id,status:"loading"});
 useEffect(()=>{if(id===null)return;let active=true;const controller=new AbortController();
 setState({id,status:"loading"});
 fetchTicket(id,controller.signal).then(ticket=>{if(active)setState({id,status:"ready",ticket});}).catch(error=>{if(active)setState({id,status:error instanceof TicketFailure&&error.status===404?"missing":"error"});});
 return ()=>{active=false;controller.abort();};},[id]);
 return state.id===id?state:{id,status:"loading"};
}

